eval:
// ⛔ NOT TRAINING MODE. Training auto-refills 26hp/s, so a landed hit was healed
// before the take ended and every phase reported dmgTaken 0 — which reads as
// "i-frames always work" when it actually means the scoreboard was being wiped.
// 2P with cpuMode off = nobody acts unless this script says so, and no regen.

// ⛔ A HITBOX EXISTS BEFORE IT IS LIVE. spawnHitbox pushes it at swing start with a
// `delay`, so `hitboxes.length>0` is true on frame 1. Live == a box whose delay burned down.
window.__live = () => player2.hitboxes.some(h => h.delay <= 0);

const reset = () => { const p1=player1,p2=player2;
  p1.hp=p1.maxHp; p2.hp=p2.maxHp;
  p1.x=380; p2.x=470; p1.facing=1; p2.facing=-1;
  p1.rollTimer=0; p1.rollRecover=0; p1.rollStale=0; p1.stunTimer=0;
  p1.vx=0; p1.vy=0; p2.vx=0; p1.hitboxes.length=0; p2.hitboxes.length=0;
  p1.recoveryTimer=0; p2.recoveryTimer=0; };

window.__calib = () => new Promise(res => { reset();
  const t0=performance.now(); player2.executeAttack(STATE.ATTACK_HEAVY);
  const tick=()=>{ const now=performance.now()-t0;
    if(window.__live()) return res(Math.round(now));
    if(now<1200) requestAnimationFrame(tick); else res(null); };
  requestAnimationFrame(tick); });

// Put P1 exactly `frac` through its roll when the box goes live. The roll cannot
// start before t=0, so for a LATE frac the ATTACK is delayed instead — clamping only
// the roll silently collapsed 0.85 and 0.45 onto the same instant.
window.__take = (frac, liveMs) => new Promise(res => { reset();
  const p1=player1, p2=player2;
  const want = frac*ROLL_TIME*1000;
  const rollAt = Math.max(0, liveMs - want), atkAt = Math.max(0, want - liveMs);
  const t0=performance.now();
  let rolled=false, swung=false, invAtHit=null, dmg=0, pctAtHit=null;
  const tick=()=>{ const now=performance.now()-t0;
    if(!swung  && now>=atkAt ){ p2.executeAttack(STATE.ATTACK_HEAVY); swung=true; }
    if(!rolled && now>=rollAt){ p1.startRoll(1); rolled=true; }
    if(invAtHit===null && swung && window.__live()){
      invAtHit = p1.rollIFrames();
      pctAtHit = p1.rollTimer>0 ? Math.round((1-p1.rollTimer/ROLL_TIME)*100) : null; }
    // grab the damage AT the drop; nothing here should heal, but never trust that again
    if(!dmg && p1.hp < p1.maxHp) dmg = p1.maxHp - p1.hp;
    if(now<1300) requestAnimationFrame(tick);
    else res({ askedPct: Math.round(frac*100)+'%', actualRollPctAtHit: pctAtHit,
               intangible: invAtHit, dmgTaken: Math.round(dmg),
               result: dmg ? 'HIT' : 'passed through' }); };
  requestAnimationFrame(tick); });
return 'scene armed'
